 84	export function isUsageStatus(value: unknown): value is UsageStatus {
 85	  const record = (item: unknown): item is Record<string, unknown> => !!item && typeof item === 'object' && !Array.isArray(item);
 86	  const text = (item: unknown, max = 160): item is string => typeof item === 'string' && item.length <= max;
 87	  const date = (item: unknown) => item === null || (text(item, 40) && Number.isFinite(Date.parse(item)));
 88	  const amount = (item: unknown) => item === null || (typeof item === 'number' && Number.isFinite(item) && item >= 0);
 89	  const percent = (item: unknown) => amount(item) && (item === null || (item as number) <= 100);
 90	  const metricKind = (item: unknown) => item === 'provider-reported-quota' || item === 'calculated-estimate';
 91	  if (!record(value) || value.schemaVersion !== USAGE_SCHEMA_VERSION || value.viewId !== USAGE_VIEW_ID
 92	    || value.generatedAt === null || !date(value.generatedAt) || !Array.isArray(value.accounts) || value.accounts.length > 20) return false;
 93	  const ids = new Set<string>();
 94	  return value.accounts.every((account) => {
 95	    if (!record(account) || !text(account.id, 64) || !/^[a-zA-Z0-9_-]+$/.test(account.id) || ids.has(account.id)
 96	      || !text(account.label, 80) || !text(account.provider, 32) || !['codex-chatgpt', 'claude-code', 'antigravity', 'cursor'].includes(account.provider)
 97	      || !text(account.source) || !(account.plan === null || text(account.plan, 80)) || !date(account.observedAt)
 98	      || !text(account.state, 32) || !['ok', 'partial', 'blocked', 'unauthorized', 'unavailable', 'unsupported'].includes(account.state)
 99	      || !Array.isArray(account.windows) || account.windows.length > 100 || !Array.isArray(account.errors) || account.errors.length > 20) return false;
100	    ids.add(account.id);
101	    const windows = new Set<string>();
102	    if (!account.windows.every((window) => {
103	      if (!record(window) || !text(window.limitId) || !text(window.label) || window.kind !== 'provider-reported-quota'
104	        || !percent(window.usedPercent) || !percent(window.remainingPercent)
105	        || !(window.usedKind === undefined || metricKind(window.usedKind)) || !metricKind(window.remainingKind)
106	        || !amount(window.durationMinutes) || !date(window.resetsAt)) return false;
107	      const key = JSON.stringify([window.limitId, window.label]);
108	      if (windows.has(key)) return false;
109	      windows.add(key);
110	      return true;
111	    })) return false;
112	    if (!account.errors.every((error) => record(error) && text(error.code, 80) && text(error.message, 500))) return false;
113	    if (!(account.ordinaryUsageAllowed === undefined || account.ordinaryUsageAllowed === null || typeof account.ordinaryUsageAllowed === 'boolean')) return false;
114	    if (account.limitAccess !== undefined) {
115	      if (!Array.isArray(account.limitAccess) || account.limitAccess.length > 50) return false;
116	      const limits = new Set<string>();
117	      if (!account.limitAccess.every((limit) => {
118	        if (!record(limit) || !text(limit.limitId) || !text(limit.label) || limits.has(limit.limitId)
119	          || !(limit.rateLimitReachedType === null || (typeof limit.rateLimitReachedType === 'string' && CODEX_LIMIT_REASONS.includes(limit.rateLimitReachedType as CodexLimitReason)))
120	          || !(limit.spendControlReached === null || typeof limit.spendControlReached === 'boolean')) return false;
121	        limits.add(limit.limitId);
122	        return true;
123	      })) return false;
124	    }
125	    const credits = account.resetCredits;
126	    if (credits !== null && (!record(credits) || !Number.isInteger(credits.availableCount)
127	      || (credits.availableCount as number) < 0 || !date(credits.earliestExpiry))) return false;
128	    const spend = account.spend;
129	    return spend === undefined || (record(spend) && spend.kind === 'provider-reported-spend' && spend.currency === 'USD'
130	      && amount(spend.used) && amount(spend.limit) && amount(spend.includedUsed) && date(spend.periodStart) && date(spend.periodEnd));
131	  });
132	}
