134	export function createUsageStatus(accounts: UsageAccount[], now = new Date()): UsageStatus {
135	  return { schemaVersion: USAGE_SCHEMA_VERSION, viewId: USAGE_VIEW_ID, generatedAt: now.toISOString(), accounts };
136	}
