138	export function usageFreshness(observedAt: string | null, now = Date.now()): 'No observation' | 'Stale' | 'Current' {
139	  if (!observedAt || !Number.isFinite(Date.parse(observedAt))) return 'No observation';
140	  return now - Date.parse(observedAt) > 5 * 60_000 ? 'Stale' : 'Current';
141	}
