143	export function usageText(status: UsageStatus, now = new Date()): string {
144	  if (status.accounts.length === 0) return 'No usage accounts are configured.';
145	  return status.accounts.map((account) => {
146	    const windows = account.windows.map((window) => `${window.label}: ${window.remainingPercent === null ? 'remaining unknown' : `${window.remainingKind === 'calculated-estimate' ? '~' : ''}${window.remainingPercent}% remaining (${window.remainingKind === 'calculated-estimate' ? 'calculated from provider-reported usage' : 'provider-reported quota'})`}, resets ${window.resetsAt ?? 'unavailable'}`);
147	    const spend = account.spend ? `USD ${account.spend.used ?? 'unknown'} on-demand spend${account.spend.limit === null ? '; limit unavailable' : ` of ${account.spend.limit} limit`}; spending cap is not remaining subscription quota` : '';
148	    const errors = account.errors.map((error) => `${error.code}: ${error.message}`);
149	    const permission = account.ordinaryUsageAllowed === undefined ? '' : `ordinary included usage ${account.ordinaryUsageAllowed === null ? 'permission unavailable' : account.ordinaryUsageAllowed ? 'allowed by provider' : 'blocked by provider (quota percentages do not override this denial)'}`;
150	    const limits = (account.limitAccess ?? []).map((limit) => `${limit.label}: reached-limit reason ${limit.rateLimitReachedType ?? 'unavailable'}; spend control ${limit.spendControlReached === null ? 'unavailable' : limit.spendControlReached ? 'reached' : 'not reached'}`);
151	    const freshness = usageFreshness(account.observedAt, now.getTime());
152	    const snapshot = account.provider === 'claude-code' || account.provider === 'antigravity' ? '; last collected CLI snapshot, not a live provider read' : '';
153	    return `${account.label} (${account.provider}; ${account.state}; source ${account.source}; observed ${account.observedAt ?? 'never'}; ${freshness}${freshness === 'Stale' ? ' (older than 5 minutes)' : ''}${snapshot}): ${[permission, ...limits, ...windows, spend, ...errors].filter(Boolean).join('; ') || 'usage unavailable'}`;
154	  }).join('\n');
155	}
