 29	export function sanitizeSnapshot(profile: SnapshotProfile, input: unknown): unknown {
 30	  const raw = object(input);
 31	  const result: JsonObject = {};
 32	  if (profile.provider === 'claude-code') {
 33	    if (!has(raw, 'rate_limits')) return result;
 34	    const limits = object(own(raw, 'rate_limits'));
 35	    if (!limits) return { rate_limits: null };
 36	    const clean: JsonObject = {};
 37	    for (const key of ['five_hour', 'seven_day']) {
 38	      if (!has(limits, key)) continue;
 39	      const window = object(own(limits, key));
 40	      clean[key] = {
 41	        used_percentage: boundedNumber(own(window, 'used_percentage'), 100),
 42	        resets_at: boundedNumber(own(window, 'resets_at'), MAX_SECONDS)
 43	      };
 44	    }
 45	    return { rate_limits: clean };
 46	  }
 47	  if (has(raw, 'plan_tier')) result.plan_tier = safeName(own(raw, 'plan_tier'));
 48	  if (!has(raw, 'quota')) return result;
 49	  const quota = object(own(raw, 'quota'));
 50	  if (!quota) return { ...result, quota: null };
 51	  const clean: JsonObject = {};
 52	  let count = 0;
 53	  for (const key of Object.keys(quota)) {
 54	    if (!safeName(key)) continue;
 55	    if (count++ >= MAX_WINDOWS) break;
 56	    const bucket = object(own(quota, key));
 57	    const item: JsonObject = { remaining_fraction: boundedNumber(own(bucket, 'remaining_fraction'), 1) };
 58	    if (has(bucket, 'reset_time')) item.reset_time = isoTime(own(bucket, 'reset_time'));
 59	    if (has(bucket, 'reset_in_seconds')) item.reset_in_seconds = boundedNumber(own(bucket, 'reset_in_seconds'), MAX_SECONDS);
 60	    clean[key] = item;
 61	  }
 62	  result.quota = clean;
 63	  return result;
 64	}
