 66	function emptyAccount(profile: SnapshotProfile): UsageAccount {
 67	  return {
 68	    id: profile.id.slice(0, 64), label: profile.label.replace(/[\x00-\x1f\x7f]/g, '').slice(0, 128), provider: profile.provider,
 69	    source: profile.provider === 'claude-code' ? 'Claude Code status-line snapshot' : 'Antigravity CLI status-line snapshot',
 70	    plan: null, observedAt: null, state: 'unavailable', windows: [], resetCredits: null, errors: []
 71	  };
 72	}
