 74	function normalize(profile: SnapshotProfile, input: unknown, observedAt: Date): UsageAccount {
 75	  const account = emptyAccount(profile);
 76	  const time = observedAt.getTime();
 77	  if (!Number.isFinite(time) || time < 0 || time > Date.now() || time > MAX_SECONDS * 1000) {
 78	    account.errors.push({ code: 'invalid_observation', message: 'Snapshot observation time is invalid or in the future.' });
 79	    return account;
 80	  }
 81	  account.observedAt = observedAt.toISOString();
 82	  const data = object(sanitizeSnapshot(profile, input));
 83	  let incomplete = false;
 84	  if (profile.provider === 'claude-code') {
 85	    const limits = object(own(data, 'rate_limits'));
 86	    for (const [key, label, duration] of [['five_hour', 'Five-hour quota', 300], ['seven_day', 'Seven-day quota', 10080]] as const) {
 87	      if (!has(limits, key)) { incomplete = true; continue; }
 88	      const raw = object(own(limits, key));
 89	      const used = boundedNumber(own(raw, 'used_percentage'), 100);
 90	      const resetsAt = secondsTime(own(raw, 'resets_at'));
 91	      account.windows.push({
 92	        limitId: key, label, kind: 'provider-reported-quota', usedPercent: used, usedKind: 'provider-reported-quota',
 93	        remainingPercent: used === null ? null : 100 - used, remainingKind: 'calculated-estimate', durationMinutes: duration, resetsAt
 94	      });
 95	      if (used === null || resetsAt === null) incomplete = true;
 96	    }
 97	  } else {
 98	    account.plan = safeName(own(data, 'plan_tier'));
 99	    const quota = object(own(data, 'quota'));
100	    const entries = quota ? Object.entries(quota) : [];
101	    if (entries.length >= MAX_WINDOWS) incomplete = true;
102	    for (const [key, value] of entries) {
103	      const raw = object(value);
104	      const fraction = boundedNumber(own(raw, 'remaining_fraction'), 1);
105	      const remaining = fraction === null ? null : Math.round(fraction * 10000) / 100;
106	      let resetsAt = isoTime(own(raw, 'reset_time'));
107	      // An explicitly unavailable absolute reset must not be replaced by a countdown.
108	      if (!has(raw, 'reset_time')) {
109	        const seconds = boundedNumber(own(raw, 'reset_in_seconds'), MAX_SECONDS);
110	        if (seconds !== null) resetsAt = secondsTime(time / 1000 + seconds);
111	      }
112	      const window: UsageWindow = {
113	        limitId: key, label: key, kind: 'provider-reported-quota', usedPercent: remaining === null ? null : Math.round((100 - remaining) * 100) / 100,
114	        usedKind: 'calculated-estimate', remainingPercent: remaining, remainingKind: 'provider-reported-quota', durationMinutes: null, resetsAt
115	      };
116	      account.windows.push(window);
117	      if (remaining === null || resetsAt === null) incomplete = true;
118	    }
119	  }
120	  if (!account.windows.some((window) => window.usedPercent !== null || window.remainingPercent !== null)) {
121	    account.errors.push({ code: 'missing_quota', message: profile.provider === 'claude-code'
122	      ? 'Claude Code subscription quota is unavailable. Rate limits require Pro or Max and may be absent before the first API response.'
123	      : 'Antigravity did not supply a readable quota bucket.' });
124	  } else if (incomplete) {
125	    account.state = 'partial';
126	    account.errors.push({ code: 'partial_quota', message: 'Some quota windows or reset times are unavailable; at most 32 windows are retained.' });
127	  } else account.state = 'ok';
128	  return account;
129	}
