139	export function normalizeSnapshot(profile: SnapshotProfile, input: unknown, observedAt: Date): UsageAccount {
140	  return profile.provider === 'claude-code' ? normalizeClaudeSnapshot(profile, input, observedAt) : normalizeAntigravitySnapshot(profile, input, observedAt);
