143	export async function readSnapshotProfile(profile: SnapshotProfile): Promise<UsageAccount> {
144	  const unavailable = (code: string, message: string) => {
145	    const account = emptyAccount(profile);
146	    account.errors.push({ code, message });
147	    return account;
148	  };
149	  let handle;
150	  try {
151	    // Nonblocking open and regular-file validation avoid hanging on special files.
152	    handle = await open(profile.snapshotFile, constants.O_RDONLY | constants.O_NONBLOCK);
153	    const info = await handle.stat();
154	    if (!info.isFile()) return unavailable('invalid_snapshot', 'Snapshot must be a regular JSON file.');
155	    if (info.size > MAX_BYTES) return unavailable('snapshot_too_large', 'Snapshot exceeds the 64 KiB size limit.');
156	    const buffer = Buffer.alloc(MAX_BYTES + 1);
157	    let length = 0;
158	    while (length < buffer.length) {
159	      const { bytesRead } = await handle.read(buffer, length, buffer.length - length, length);
160	      if (!bytesRead) break;
161	      length += bytesRead;
162	    }
163	    if (length > MAX_BYTES) return unavailable('snapshot_too_large', 'Snapshot exceeds the 64 KiB size limit.');
164	    let envelope: JsonObject | null;
165	    try { envelope = object(JSON.parse(buffer.toString('utf8', 0, length))); }
166	    catch { return unavailable('invalid_snapshot', 'Snapshot is not valid JSON.'); }
167	    if (!envelope || own(envelope, 'schemaVersion') !== 1 || own(envelope, 'provider') !== profile.provider || own(envelope, 'accountId') !== profile.id || !has(envelope, 'data')) {
168	      return unavailable('snapshot_mismatch', 'Snapshot version, provider, or account does not match this profile.');
169	    }
170	    const timestamp = isoTime(own(envelope, 'observedAt'));
171	    if (timestamp === null || Date.parse(timestamp) > Date.now()) return unavailable('invalid_observation', 'Snapshot observation time is invalid or in the future.');
172	    return normalizeSnapshot(profile, own(envelope, 'data'), new Date(timestamp));
173	  } catch {
174	    return unavailable('snapshot_read_failed', 'Could not read the configured snapshot file.');
175	  } finally {
176	    await handle?.close().catch(() => {});
177	  }
178	}

