 25	export function normalizeCodexRead(profile: UsageProfile, accountResult: unknown, limitResult: unknown, observedAt: Date): UsageAccount {
 26	  const account = object(object(accountResult)?.account);
 27	  const base: UsageAccount = {
 28	    id: profile.id, label: profile.label, provider: 'codex-chatgpt', source: 'Codex app-server',
 29	    plan: string(account?.planType, 80), observedAt: observedAt.toISOString(), state: 'ok', windows: [], resetCredits: null,
 30	    ordinaryUsageAllowed: null, limitAccess: [], errors: []
 31	  };
 32	  if (!account || account.type !== 'chatgpt') {
 33	    base.state = account ? 'unsupported' : 'unauthorized';
 34	    base.errors.push({ code: base.state, message: account ? 'Profile is not signed in with ChatGPT.' : 'Profile is not signed in.' });
 35	    return base;
 36	  }
 37	  const result = object(limitResult);
 38	  const permission = result?.ordinaryUsageAllowed;
 39	  base.ordinaryUsageAllowed = typeof permission === 'boolean' ? permission : null;
 40	  const buckets = object(result?.rateLimitsByLimitId);
 41	  const entries: Array<[string, unknown]> = buckets && Object.keys(buckets).length ? Object.entries(buckets) : [['codex', result?.rateLimits]];
 42	  let incomplete = entries.length > 50 || (permission !== undefined && permission !== null && typeof permission !== 'boolean');
 43	  let bucketBlocked = false;
 44	  const addError = (code: string, message: string) => {
 45	    if (base.errors.length < 20 && !base.errors.some((error) => error.code === code)) base.errors.push({ code, message });
 46	  };
 47	  if (permission === false) addError('ordinary_usage_denied', 'Codex reports that ordinary included usage is blocked; quota percentages and reset times do not override this permission.');
 48	  const bucketIds = new Map<string, number>();
 49	  for (const [key, raw] of entries.slice(0, 50)) {
 50	    const bucket = object(raw);
 51	    const id = bucket && (string(bucket.limitId) ?? string(key));
 52	    if (id) bucketIds.set(id, (bucketIds.get(id) ?? 0) + 1);
 53	  }
 54	  const windowKeys = new Set<string>();
 55	  for (const [key, raw] of entries.slice(0, 50)) {
 56	    const bucket = object(raw);
 57	    if (!bucket) { incomplete = true; continue; }
 58	    const id = string(bucket.limitId) ?? string(key);
 59	    if (!id) { incomplete = true; continue; }
 60	    // Neither conflicting bucket is authoritative when the same ID appears more than once.
 61	    if (bucketIds.get(id)! > 1) { incomplete = true; continue; }
 62	    const label = string(bucket.limitName) ?? id;
 63	    const rawReason = bucket.rateLimitReachedType;
 64	    const reason = typeof rawReason === 'string' && CODEX_LIMIT_REASONS.includes(rawReason as CodexLimitReason) ? rawReason as CodexLimitReason : null;
