    ...Array.from({ length: 4 }, (_, index) => accounts.addProvider({ provider: 'claude-code', label: `Claude ${index}` })),
    ...Array.from({ length: 4 }, (_, index) => accounts.addProvider({ provider: 'antigravity', label: `Google ${index}` })),
