import { execFile } from 'node:child_process';
import { constants } from 'node:fs';
import { open } from 'node:fs/promises';
import { homedir } from 'node:os';

/**
 * Read-only access to sign-ins that another CLI stored on this computer. Used only when the
 * user turns on local credential reading. Nothing here refreshes, writes, or logs a credential,
 * and child-process errors are never surfaced because they can contain the secret.
 */
export type SecretReader = (service: string, account?: string) => Promise<string | null>;

/** macOS login keychain lookup through the system `security` tool. Other platforms return null. */
export const readKeychainSecret: SecretReader = (service, account) => {
  if (process.platform !== 'darwin') return Promise.resolve(null);
  const args = ['find-generic-password', '-s', service, ...(account ? ['-a', account] : []), '-w'];
  return new Promise((resolve) => {
    // A first read can show a macOS access prompt, so allow time for the user to answer it.
    const child = execFile('/usr/bin/security', args, {
      env: { HOME: homedir(), PATH: '/usr/bin:/bin' }, encoding: 'utf8', timeout: 60_000, killSignal: 'SIGKILL', maxBuffer: 64 * 1024,
    }, (error, stdout) => resolve(error ? null : stdout.trim() || null));
    child.stdin?.end();
  });
};

/** Reads a small regular file without following links or blocking on special files. */
export async function readSmallFile(path: string, maxBytes = 64 * 1024): Promise<string | null> {
  let handle;
  try {
    handle = await open(path, constants.O_RDONLY | constants.O_NONBLOCK | (constants.O_NOFOLLOW ?? 0));
    const info = await handle.stat();
    if (!info.isFile() || info.size > maxBytes) return null;
    const buffer = Buffer.alloc(maxBytes + 1);
    const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
    return bytesRead > maxBytes ? null : buffer.subarray(0, bytesRead).toString('utf8');
  } catch { return null; }
  finally { await handle?.close().catch(() => {}); }
}

export async function fileExists(path: string): Promise<boolean> {
  let handle;
  try { handle = await open(path, constants.O_RDONLY | constants.O_NONBLOCK); return true; }
  catch (error) { return (error as NodeJS.ErrnoException)?.code !== 'ENOENT'; }
  finally { await handle?.close().catch(() => {}); }
}

/** Unverified JWT claims, used only to read expiry and the signed-in email for display. */
export function jwtClaims(token: string): Record<string, unknown> | null {
  const part = token.split('.')[1];
  if (!part || part.length > 16_384) return null;
  try {
    const value = JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch { return null; }
}

/** Fetches JSON from a fixed HTTPS origin with a timeout, no redirects, and a response size bound. */
export async function fetchJson(url: string, init: { headers: Record<string, string>; method?: string; body?: string },
  options: { fetch?: typeof globalThis.fetch; timeoutMs?: number; maxBytes?: number } = {}): Promise<{ status: number; json: unknown }> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? 15_000);
  try {
    const response = await (options.fetch ?? globalThis.fetch)(url, { ...init, redirect: 'error', credentials: 'omit', signal: controller.signal });
    const text = await response.text();
    if (text.length > (options.maxBytes ?? 512 * 1024)) return { status: response.status, json: null };
    let json: unknown = null;
    try { json = text ? JSON.parse(text) : null; } catch { json = null; }
    return { status: response.status, json };
  } finally { clearTimeout(timer); }
}

import { createHash } from 'node:crypto';
import { userInfo } from 'node:os';
import { join, resolve } from 'node:path';
import type { UsageAccount, UsageWindow } from './index.js';
import { fetchJson, readKeychainSecret, readSmallFile, type SecretReader } from './local-auth.js';

/**
 * Live Claude subscription usage from the Claude Code sign-in stored for one config directory.
 * Opt-in only. It reads the stored OAuth access token, never the refresh token's endpoint:
 * Anthropic rotates refresh tokens, so refreshing here would sign the CLI out. Freshness is
 * left to `claude auth status`, which the host runs first. The usage endpoint is the one
 * Claude Code itself calls; it is not a documented public API and can change.
 */
const USAGE_URL = 'https://api.anthropic.com/api/oauth/usage';
const KEYCHAIN_SERVICE = 'Claude Code-credentials';

export interface ClaudeOAuthProfile { id: string; label: string; claudeConfigDir: string }

interface StoredClaude { accessToken: string; expiresAt: number | null; subscriptionType: string | null }

const object = (value: unknown): Record<string, unknown> | null => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
const percent = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) ? Math.min(100, Math.max(0, Math.round(value * 10) / 10)) : null;
const isoTime = (value: unknown): string | null => {
  if (typeof value !== 'string' || value.length > 40) return null;
  const time = Date.parse(value);
  return Number.isFinite(time) ? new Date(time).toISOString() : null;
};

function parseStored(text: string | null): StoredClaude | null {
  if (!text) return null;
  let raw = text.trim();
  // Some keychain entries are stored hex-encoded.
  if (!raw.startsWith('{') && /^[0-9a-f]+$/i.test(raw) && raw.length % 2 === 0) raw = Buffer.from(raw, 'hex').toString('utf8');
  try {
    const oauth = object(object(JSON.parse(raw))?.claudeAiOauth);
    const accessToken = typeof oauth?.accessToken === 'string' && oauth.accessToken.length < 8192 ? oauth.accessToken : null;
    if (!accessToken) return null;
    return {
      accessToken,
      expiresAt: typeof oauth?.expiresAt === 'number' && Number.isFinite(oauth.expiresAt) ? oauth.expiresAt : null,
      subscriptionType: typeof oauth?.subscriptionType === 'string' && /^[a-z0-9_-]{1,40}$/i.test(oauth.subscriptionType) ? oauth.subscriptionType : null,
    };
  } catch { return null; }
}

/** Claude Code names the keychain item for a custom config directory by the first 8 hex of its SHA-256. */
export function claudeKeychainService(configDir: string, isDefault: boolean): string {
  return isDefault ? KEYCHAIN_SERVICE : `${KEYCHAIN_SERVICE}-${createHash('sha256').update(configDir.normalize('NFC')).digest('hex').slice(0, 8)}`;
}

async function readStored(configDir: string, isDefault: boolean, readSecret: SecretReader): Promise<StoredClaude | null> {
  let account: string | undefined;
  try { account = userInfo().username; } catch { account = undefined; }
  // Try the spellings a user may have exported as CLAUDE_CONFIG_DIR.
  const spellings = isDefault ? [configDir] : [...new Set([configDir, `${configDir}/`, resolve(configDir)])];
  for (const spelling of spellings) {
    const service = claudeKeychainService(spelling, isDefault);
    const stored = parseStored(await readSecret(service, account)) ?? parseStored(account ? await readSecret(service) : null);
    if (stored) return stored;
  }
  return parseStored(await readSmallFile(join(configDir, '.credentials.json')));
}

export function normalizeClaudeOAuthUsage(profile: ClaudeOAuthProfile, input: unknown, observedAt: Date, plan: string | null = null): UsageAccount {
  const root = object(input);
  const windows: UsageWindow[] = [];
  const seen = new Set<string>();
  const push = (limitId: string, label: string, used: number | null, resetsAt: string | null, durationMinutes: number) => {
    if ((used === null && !resetsAt) || seen.has(limitId) || windows.length >= 20) return;
    seen.add(limitId);
    windows.push({
      limitId, label, kind: 'provider-reported-quota', usedPercent: used, usedKind: 'provider-reported-quota',
      remainingPercent: used === null ? null : Math.round((100 - used) * 10) / 10, remainingKind: 'calculated-estimate', durationMinutes, resetsAt,
    });
  };
  for (const [key, label, minutes] of [['five_hour', 'Five-hour quota', 300], ['seven_day', 'Seven-day quota', 10080]] as const) {
    const window = object(root?.[key]);
    if (window) push(key, label, percent(window.utilization), isoTime(window.resets_at), minutes);
  }
  // Per-model weekly limits arrive as weekly_scoped entries; older responses used seven_day_<model>.
  for (const entry of Array.isArray(root?.limits) ? root.limits.slice(0, 20) : []) {
    const scoped = object(entry);
    const name = object(object(scoped?.scope)?.model)?.display_name;
    if (scoped?.kind !== 'weekly_scoped' || typeof name !== 'string') continue;
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '');
    if (!slug || slug.length > 24) continue;
    push(`seven_day_${slug}`, `Seven-day ${name.slice(0, 24)} quota`, percent(scoped.percent), isoTime(scoped.resets_at), 10080);
  }
  for (const model of ['fable', 'opus', 'sonnet', 'haiku']) {
    const window = object(root?.[`seven_day_${model}`]);
    if (window) push(`seven_day_${model}`, `Seven-day ${model} quota`, percent(window.utilization), isoTime(window.resets_at), 10080);
  }
  const incomplete = windows.some((window) => window.usedPercent === null || window.resetsAt === null);
  return {
    id: profile.id, label: profile.label, provider: 'claude-code', source: 'Claude usage (local sign-in)', plan,
    observedAt: observedAt.toISOString(), state: windows.length ? (incomplete ? 'partial' : 'ok') : 'partial', windows, resetCredits: null,
    errors: windows.length ? [] : [{ code: 'missing_quota', message: 'Claude returned no subscription usage windows for this sign-in.' }],
  };
}

export type ClaudeOAuthResult =
  | { kind: 'ok'; account: UsageAccount }
  | { kind: 'no-credential' }
  | { kind: 'error'; code: string; message: string; state: UsageAccount['state'] };

export async function readClaudeOAuthUsage(profile: ClaudeOAuthProfile, options: {
  isDefault: boolean; fetch?: typeof globalThis.fetch; readSecret?: SecretReader; now?: () => number;
}): Promise<ClaudeOAuthResult> {
  const stored = await readStored(resolve(profile.claudeConfigDir), options.isDefault, options.readSecret ?? readKeychainSecret);
  if (!stored) return { kind: 'no-credential' };
  const now = options.now?.() ?? Date.now();
  if (stored.expiresAt !== null && stored.expiresAt <= now) {
    return { kind: 'error', code: 'claude_token_expired', state: 'unauthorized', message: 'The local Claude Code sign-in has expired. Open Claude Code with this account to refresh it.' };
  }
  try {
    const response = await fetchJson(USAGE_URL, { headers: {
      Authorization: `Bearer ${stored.accessToken}`, Accept: 'application/json', 'anthropic-beta': 'oauth-2025-04-20', 'User-Agent': 'subset-usage/0.0.0',
    } }, { fetch: options.fetch });
    if (response.status === 401 || response.status === 403) return { kind: 'error', code: 'claude_unauthorized', state: 'unauthorized', message: 'Claude rejected the local sign-in. Open Claude Code with this account to sign in again.' };
    if (response.status === 429) return { kind: 'error', code: 'claude_rate_limited', state: 'unavailable', message: 'Claude is rate-limiting usage checks. Try again in a few minutes.' };
    if (response.status < 200 || response.status >= 300 || !object(response.json)) return { kind: 'error', code: 'claude_request_failed', state: 'unavailable', message: 'Could not read Claude usage for this sign-in.' };
    return { kind: 'ok', account: normalizeClaudeOAuthUsage(profile, response.json, new Date(), stored.subscriptionType) };
  } catch {
    return { kind: 'error', code: 'claude_request_failed', state: 'unavailable', message: 'Could not read Claude usage for this sign-in.' };
  }
}

import { createDecipheriv } from 'node:crypto';
import { join, resolve } from 'node:path';
import { isEmail, type UsageAccount, type UsageWindow } from './index.js';
import { fetchJson, fileExists, jwtClaims, readKeychainSecret, readSmallFile, type SecretReader } from './local-auth.js';

/**
 * Factory Droid rate limits from the endpoint Droid's own /limits view calls. Factory does not
 * document it, so it can change without notice. Two read-only authorization modes:
 * - a Factory API key the user supplies through a named environment variable, or
 * - (opt-in) the Droid sign-in stored under one Factory home, decrypted with its key from the OS
 *   keychain or key file. Tokens are never refreshed or written; an expired one asks the user to run Droid.
 */
export interface FactoryProfile {
  id: string;
  label: string;
  provider: 'factory-droid';
  /** Directory whose `.factory` folder holds this account (FACTORY_HOME_OVERRIDE, or the user's home). */
  factoryHome: string;
  credentialEnv?: string;
}

const API = { global: 'https://api.factory.ai', eu: 'https://api.eu.factory.ai' } as const;
const object = (value: unknown): Record<string, unknown> | null => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
const text = (value: unknown, max = 256): string | null => typeof value === 'string' && value.length > 0 && value.length <= max ? value : null;
const percent = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) ? Math.min(100, Math.max(0, Math.round(value * 10) / 10)) : null;
const isoTime = (value: unknown): string | null => {
  if (typeof value !== 'string' && typeof value !== 'number') return null;
  const time = typeof value === 'number' ? value : Date.parse(value);
  return Number.isFinite(time) && time > 0 && time < 253402300799000 ? new Date(time).toISOString() : null;
};

interface FactoryAuth { token: string; orgId: string | null; region: 'global' | 'eu'; email: string | null; expiresAt: number | null }

/** Factory's v2 store is `base64(iv):base64(tag):base64(ciphertext)`, AES-256-GCM. */
export function decryptFactoryCredential(contents: string, key: Buffer): unknown {
  const parts = contents.trim().split(':');
  if (key.length !== 32 || parts.length !== 3) return null;
  try {
    const [iv, tag, data] = parts.map((part) => Buffer.from(part, 'base64'));
    if (iv.length !== 16 || tag.length !== 16 || !data.length) return null;
    const decipher = createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(tag);
    return JSON.parse(Buffer.concat([decipher.update(data), decipher.final()]).toString('utf8'));
  } catch { return null; }
}

const decodeKey = (value: string | null): Buffer | null => {
  const trimmed = value?.trim() ?? '';
  if (!/^[A-Za-z0-9+/]{43}=$/.test(trimmed)) return null;
  const key = Buffer.from(trimmed, 'base64');
  return key.length === 32 ? key : null;
};

/** Returns the stored sign-in, `null` when none exists, or `'unreadable'` when one exists but cannot be opened. */
export async function readFactoryLocalAuth(factoryHome: string, readSecret: SecretReader = readKeychainSecret): Promise<FactoryAuth | null | 'unreadable'> {
  const directory = join(resolve(factoryHome), '.factory');
  const layouts = [
    ['auth.v2.loginkeychain', 'auth-encryption-key-security-cli'],
    ['auth.v2.keyring', 'auth-encryption-key'],
    ['auth.v2.file', null],
  ] as const;
  for (const [name, keychainAccount] of layouts) {
    const path = join(directory, name);
    if (!(await fileExists(path))) continue;
    // A newer store that exists but cannot be read must not fall back to an older account's file.
    const contents = await readSmallFile(path);
    const key = decodeKey(keychainAccount ? await readSecret('Factory CLI', keychainAccount) : await readSmallFile(join(directory, 'auth.v2.key')));
    if (!contents || !key) return 'unreadable';
    try {
      const record = object(decryptFactoryCredential(contents, key));
      const token = text(record?.access_token, 16_384);
      if (!token) return 'unreadable';
      const claims = jwtClaims(token);
      return {
        token, orgId: text(record?.active_organization_id, 128), region: record?.region === 'eu' ? 'eu' : 'global',
        email: isEmail(claims?.email) ? claims.email : null,
        expiresAt: typeof claims?.exp === 'number' ? claims.exp * 1000 : null,
      };
    } finally { key.fill(0); }
  }
  return null;
}

export function normalizeFactoryLimits(profile: FactoryProfile, input: unknown, observedAt: Date, auth: { email: string | null; source: string }): UsageAccount {
  const root = object(input);
  const limits = object(root?.limits);
  const base: UsageAccount = {
    id: profile.id, label: profile.label, provider: 'factory-droid', source: auth.source, plan: null, email: auth.email,
    observedAt: observedAt.toISOString(), state: 'ok', windows: [], resetCredits: null, errors: [],
  };
  const standard = object(limits?.standard);
  if (root?.usesTokenRateLimitsBilling === false || !standard) {
    return { ...base, state: 'unsupported', errors: [{ code: 'factory_no_rate_limits', message: 'This Factory organization does not report personal rate limits.' }] };
  }
  const windows: UsageWindow[] = [];
  for (const [group, prefix, values] of [['standard', '', standard], ['core', 'Core ', object(limits?.core)]] as const) {
    for (const [key, label, minutes] of [['fiveHour', 'five-hour', 300], ['weekly', 'weekly', 10080], ['monthly', 'monthly', 43200]] as const) {
      const window = object(values?.[key]);
      const used = percent(window?.usedPercent);
      const resetsAt = isoTime(window?.windowEnd);
      if (!window || (used === null && !resetsAt)) continue;
      windows.push({
        limitId: `${group}_${key}`, label: `${prefix}${label} quota`, kind: 'provider-reported-quota', usedPercent: used, usedKind: 'provider-reported-quota',
        remainingPercent: used === null ? null : Math.round((100 - used) * 10) / 10, remainingKind: 'calculated-estimate', durationMinutes: minutes, resetsAt,
      });
    }
  }
  const extra = root?.extraUsageBalanceCents;
  const incomplete = windows.some((window) => window.usedPercent === null || window.resetsAt === null);
  return {
    ...base, windows, state: !windows.length || incomplete ? 'partial' : 'ok',
    ...(typeof extra === 'number' && Number.isFinite(extra) && extra >= 0
      ? { spend: { kind: 'provider-reported-spend' as const, currency: 'USD' as const, used: null, limit: null, includedUsed: null, periodStart: null, periodEnd: null, balance: Math.round(extra) / 100 } }
      : {}),
    errors: windows.length ? [] : [{ code: 'missing_limits', message: 'Factory returned no readable rate-limit windows.' }],
  };
}

export async function readFactoryProfile(profile: FactoryProfile, options: {
  localCredentials: boolean; env?: NodeJS.ProcessEnv; fetch?: typeof globalThis.fetch; readSecret?: SecretReader; now?: () => number;
}): Promise<UsageAccount> {
  const fail = (code: string, message: string, state: UsageAccount['state'] = 'unavailable'): UsageAccount => ({
    id: profile.id, label: profile.label, provider: 'factory-droid', source: 'Factory rate limits', plan: null, observedAt: null, state, windows: [], resetCredits: null,
    errors: [{ code, message }],
  });
  const now = options.now?.() ?? Date.now();
  let auth: FactoryAuth | null = null;
  let source = 'Factory rate limits (API key)';
  let localState: FactoryAuth | null | 'unreadable' = null;
  if (options.localCredentials) {
    localState = await readFactoryLocalAuth(profile.factoryHome, options.readSecret);
    if (localState && localState !== 'unreadable') {
      if (localState.expiresAt !== null && localState.expiresAt <= now) {
        if (!profile.credentialEnv) return fail('factory_token_expired', 'The local Droid sign-in has expired. Run droid with this account to refresh it.', 'unauthorized');
      } else { auth = localState; source = 'Factory rate limits (local sign-in)'; }
    }
  }
  try {
    if (!auth) {
      const env = options.env ?? process.env;
      const key = profile.credentialEnv && Object.hasOwn(env, profile.credentialEnv) ? env[profile.credentialEnv] : undefined;
      if (!key || key.length > 4096 || !/^[\x21-\x7e]+$/.test(key)) {
        if (localState === 'unreadable') return fail('factory_local_unreadable', 'Droid is signed in, but its stored sign-in could not be read. Allow keychain access, or use an API key.');
        return options.localCredentials
          ? fail('factory_signed_out', 'No Droid sign-in was found for this Factory home. Sign in with droid, or set an API key variable.', 'unauthorized')
          : fail('factory_missing_key', profile.credentialEnv ? 'The configured Factory API key variable is not set for the usage server.' : 'Add a Factory API key variable, or turn on local sign-ins in Settings.', 'unauthorized');
      }
      const whoami = await fetchJson(`${API.global}/api/cli/whoami`, { headers: { Authorization: `Bearer ${key}`, Accept: 'application/json', 'X-Factory-Whoami-Extended': 'true' } }, { fetch: options.fetch });
      if (whoami.status === 401 || whoami.status === 403) return fail('factory_unauthorized', 'Factory rejected the API key.', 'unauthorized');
      const identity = object(whoami.json);
      const orgId = text(identity?.orgId, 128);
      if (whoami.status !== 200 || !orgId || identity?.isOnPrem === true) return fail('factory_identity_failed', 'Could not identify the Factory account for this API key.');
      auth = { token: key, orgId, region: identity?.region === 'eu' ? 'eu' : 'global', email: isEmail(identity?.email) ? identity.email as string : null, expiresAt: null };
    }
    const response = await fetchJson(`${API[auth.region]}/api/billing/limits`, { headers: {
      Authorization: `Bearer ${auth.token}`, Accept: 'application/json', ...(auth.orgId ? { 'X-Factory-Org-Id': auth.orgId } : {}),
    } }, { fetch: options.fetch });
    if (response.status === 401 || response.status === 403) return fail('factory_unauthorized', 'Factory rejected this sign-in. Run droid to sign in again.', 'unauthorized');
    if (response.status === 429) return fail('factory_rate_limited', 'Factory is rate-limiting usage checks. Try again later.');
    if (response.status !== 200 || !object(response.json)) return fail('factory_request_failed', 'Could not read Factory rate limits.');
    return normalizeFactoryLimits(profile, response.json, new Date(), { email: auth.email, source });
  } catch {
    return fail('factory_request_failed', 'Could not read Factory rate limits.');
  }
}

