import { execFile } from 'node:child_process';
import { isEmail, type UsageAccount } from './index.js';

/**
 * Amp credit balance from the documented `amp usage` command. The Amp CLI owns its sign-in;
 * another saved account can be read by naming an environment variable holding that account's
 * AMP_API_KEY. The CLI prints text, so parsing is limited to the signed-in email and dollar amounts.
 */
export interface AmpProfile { id: string; label: string; provider: 'amp'; credentialEnv?: string }

const money = (value: string | undefined): number | null => {
  if (!value) return null;
  const amount = Number(value.replace(/,/g, ''));
  return Number.isFinite(amount) && amount >= 0 ? Math.round(amount * 100) / 100 : null;
};

export function normalizeAmpUsage(profile: AmpProfile, output: string, observedAt: Date): UsageAccount {
  const text = output.slice(0, 16_384);
  const email = /Signed in as\s+(\S+@\S+?)[\s(]/.exec(`${text} `)?.[1];
  const credits = money(/credits:?\**\s*\$([\d,]+(?:\.\d+)?)\s+remaining/i.exec(text)?.[1]);
  const free = money(/\$([\d,]+(?:\.\d+)?)\s+Amp Free remaining today/i.exec(text)?.[1]);
  const balances: NonNullable<UsageAccount['balances']> = [];
  if (credits !== null) balances.push({ kind: 'provider-reported-balance', currency: 'USD', amount: credits, label: 'Credits remaining', ...(free !== null ? { note: 'Includes Amp Free' } : {}) });
  if (free !== null) balances.push({ kind: 'provider-reported-balance', currency: 'USD', amount: free, label: 'Amp Free left today', note: 'Resets daily' });
  return {
    id: profile.id, label: profile.label, provider: 'amp', source: 'amp usage', plan: null, email: isEmail(email) ? email : null,
    observedAt: observedAt.toISOString(), state: balances.length ? 'ok' : 'partial', windows: [], resetCredits: null, balances,
    errors: balances.length ? [] : [{ code: 'amp_unreadable', message: 'amp usage did not report a credit balance this dashboard can read.' }],
  };
}

export function readAmpProfile(profile: AmpProfile, options: { ampBinary?: string; env?: NodeJS.ProcessEnv; timeoutMs?: number } = {}): Promise<UsageAccount> {
  const fail = (code: string, message: string, state: UsageAccount['state'] = 'unavailable'): UsageAccount => ({
    id: profile.id, label: profile.label, provider: 'amp', source: 'amp usage', plan: null, observedAt: null, state, windows: [], resetCredits: null, errors: [{ code, message }],
  });
  const base = options.env ?? process.env;
  const env: NodeJS.ProcessEnv = { ...base };
  if (profile.credentialEnv) {
    const key = Object.hasOwn(base, profile.credentialEnv) ? base[profile.credentialEnv] : undefined;
    if (!key) return Promise.resolve(fail('amp_missing_key', 'The configured Amp API key variable is not set for the usage server.', 'unauthorized'));
    env.AMP_API_KEY = key;
  }
  return new Promise((resolve) => {
    execFile(options.ampBinary ?? 'amp', ['usage'], { env, encoding: 'utf8', timeout: options.timeoutMs ?? 20_000, maxBuffer: 64 * 1024, killSignal: 'SIGKILL' }, (error, stdout) => {
      if (error) {
        // Never surface CLI output: it can include account details.
        resolve((error as NodeJS.ErrnoException).code === 'ENOENT'
          ? fail('amp_missing_cli', 'The amp CLI is not installed for the usage server.')
          : /not (signed|logged) in|login/i.test(String(stdout)) ? fail('amp_signed_out', 'Amp is not signed in. Run amp login.', 'unauthorized')
            : fail('amp_failed', 'amp usage did not finish successfully.'));
        return;
      }
      resolve(normalizeAmpUsage(profile, stdout, new Date()));
    });
  });
}

import { homedir } from 'node:os';
import { join } from 'node:path';
import { isEmail, type UsageAccount, type UsageWindow } from './index.js';
import { fetchJson, readSmallFile } from './local-auth.js';

/**
 * Devin quota from the Windsurf seat-status endpoint the Devin CLI uses (undocumented). The key
 * comes from `devin auth login`'s credentials.toml (opt-in local sign-ins) or a named environment
 * variable. Only https servers on codeium.com, windsurf.com, or devin.ai are contacted.
 */
export interface DevinProfile { id: string; label: string; provider: 'devin'; credentialEnv?: string }

const DEFAULT_SERVER = 'https://server.codeium.com';
const STATUS_PATH = '/exa.seat_management_pb.SeatManagementService/GetUserStatus';
const object = (value: unknown): Record<string, unknown> | null => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
const pick = (record: Record<string, unknown> | null, ...keys: string[]): unknown => keys.map((key) => record?.[key]).find((value) => value !== undefined && value !== null);
const number = (value: unknown): number | null => {
  const parsed = typeof value === 'string' && /^\d+(\.\d+)?$/.test(value) ? Number(value) : value;
  return typeof parsed === 'number' && Number.isFinite(parsed) ? parsed : null;
};

export function devinCredentialsFile(env: NodeJS.ProcessEnv = process.env): string {
  return join(env.XDG_DATA_HOME || join(homedir(), '.local', 'share'), 'devin', 'credentials.toml');
}

/** Reads `key = "value"` pairs from Devin's flat credentials file. */
export function parseDevinCredentials(text: string | null): { apiKey: string | null; server: string } {
  const values = new Map<string, string>();
  for (const line of (text ?? '').split('\n').slice(0, 200)) {
    const match = /^\s*([a-z_]+)\s*=\s*"([^"\n]{1,4096})"\s*$/.exec(line);
    if (match) values.set(match[1], match[2]);
  }
  return { apiKey: values.get('windsurf_api_key') ?? null, server: values.get('api_server_url') ?? DEFAULT_SERVER };
}

export function allowedDevinServer(value: string): string | null {
  try {
    const url = new URL(value);
    const host = url.hostname.toLowerCase();
    return url.protocol === 'https:' && !url.username && !url.password && ['codeium.com', 'windsurf.com', 'devin.ai'].some((domain) => host === domain || host.endsWith(`.${domain}`)) ? url.origin : null;
  } catch { return null; }
}

export function normalizeDevinStatus(profile: DevinProfile, input: unknown, observedAt: Date): UsageAccount {
  const root = object(input);
  const user = object(pick(root, 'userStatus', 'user_status')) ?? root;
  const plan = object(pick(user, 'planStatus', 'plan_status'));
  const info = object(pick(plan, 'planInfo', 'plan_info')) ?? object(pick(user, 'planInfo', 'plan_info'));
  const windows: UsageWindow[] = [];
  for (const [id, label, minutes, remainingKeys, resetKeys] of [
    ['daily', 'Daily quota', 1440, ['dailyQuotaRemainingPercent', 'daily_quota_remaining_percent'], ['dailyQuotaResetAtUnix', 'daily_quota_reset_at_unix']],
    ['weekly', 'Weekly quota', 10080, ['weeklyQuotaRemainingPercent', 'weekly_quota_remaining_percent'], ['weeklyQuotaResetAtUnix', 'weekly_quota_reset_at_unix']],
  ] as const) {
    const remaining = number(pick(plan, ...remainingKeys));
    if (remaining === null || remaining < 0 || remaining > 100) continue;
    if (id === 'daily' && (info?.hideDailyQuota === true || info?.hide_daily_quota === true)) continue;
    const reset = number(pick(plan, ...resetKeys));
    windows.push({
      limitId: id, label, kind: 'provider-reported-quota', usedPercent: Math.round((100 - remaining) * 10) / 10, usedKind: 'calculated-estimate',
      remainingPercent: remaining, remainingKind: 'provider-reported-quota', durationMinutes: minutes,
      resetsAt: reset !== null && reset > 0 && reset < 253402300799 ? new Date(reset * 1000).toISOString() : null,
    });
  }
  const planName = pick(info, 'planName', 'plan_name');
  const email = pick(user, 'email');
  return {
    id: profile.id, label: profile.label, provider: 'devin', source: 'Devin seat status', plan: typeof planName === 'string' && planName.length <= 60 ? planName : null,
    email: isEmail(email) ? email : null, observedAt: observedAt.toISOString(), state: windows.length ? 'ok' : 'partial', windows, resetCredits: null,
    errors: windows.length ? [] : [{ code: 'devin_no_quota', message: 'Devin did not report daily or weekly quota for this plan.' }],
  };
}

export async function readDevinProfile(profile: DevinProfile, options: {
  localCredentials: boolean; env?: NodeJS.ProcessEnv; fetch?: typeof globalThis.fetch; credentialsFile?: string;
}): Promise<UsageAccount> {
  const fail = (code: string, message: string, state: UsageAccount['state'] = 'unavailable'): UsageAccount => ({
    id: profile.id, label: profile.label, provider: 'devin', source: 'Devin seat status', plan: null, observedAt: null, state, windows: [], resetCredits: null, errors: [{ code, message }],
  });
  const env = options.env ?? process.env;
  let apiKey = profile.credentialEnv && Object.hasOwn(env, profile.credentialEnv) ? env[profile.credentialEnv] ?? null : null;
  let server = DEFAULT_SERVER;
  if (!apiKey && options.localCredentials) {
    const stored = parseDevinCredentials(await readSmallFile(options.credentialsFile ?? devinCredentialsFile(env)));
    apiKey = stored.apiKey;
    const allowed = allowedDevinServer(stored.server);
    if (!allowed) return fail('devin_server_rejected', 'Devin is configured for a server this dashboard does not contact.');
    server = allowed;
  }
  if (!apiKey || apiKey.length > 4096) {
    return fail('devin_signed_out', options.localCredentials ? 'Devin is not signed in. Run devin auth login.' : 'Add a Devin API key variable, or turn on local sign-ins in Settings.', 'unauthorized');
  }
  try {
    const response = await fetchJson(`${server}${STATUS_PATH}`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, Accept: 'application/json', 'Content-Type': 'application/json', 'Connect-Protocol-Version': '1' },
      body: JSON.stringify({ metadata: { apiKey, ideName: 'devin', ideVersion: '0.0.0', extensionName: 'devin', extensionVersion: '0.0.0', locale: 'en' } }),
    }, { fetch: options.fetch });
    if (response.status === 401 || response.status === 403) return fail('devin_unauthorized', 'Devin rejected this sign-in. Run devin auth login.', 'unauthorized');
    if (response.status === 429) return { ...fail('devin_rate_limited', 'Devin is rate-limiting usage checks. Try again later.'), retryAfterMs: response.retryAfterMs } as UsageAccount;
    if (response.status !== 200 || !object(response.json)) return fail('devin_request_failed', 'Could not read Devin usage.');
    return normalizeDevinStatus(profile, response.json, new Date());
  } catch {
    return fail('devin_request_failed', 'Could not read Devin usage.');
  }
}

import { homedir } from 'node:os';
import { join } from 'node:path';
import { fetchClaudeUsage } from './claude-oauth.js';
import { isEmail, type UsageAccount, type UsageWindow } from './index.js';
import { fetchJson, jwtClaims, readSmallFile } from './local-auth.js';

/**
 * Subscription usage for logins that Pi and OpenCode keep in their own auth.json (opt-in local
 * sign-ins only). Each tool refreshes its own tokens; Subset only reads them, so an expired token
 * asks the user to open the tool. ChatGPT and OpenCode Go usage come from endpoints those tools'
 * makers do not document; Claude usage reuses the Claude reader.
 */
export type StoredLoginTool = 'pi' | 'opencode';
export type StoredLoginKind = 'chatgpt' | 'claude' | 'opencode-go';
export interface StoredLoginProfile { id: string; label: string; provider: StoredLoginTool; login: StoredLoginKind; dataDir?: string }

const object = (value: unknown): Record<string, unknown> | null => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
const text = (value: unknown, max = 16_384): string | null => typeof value === 'string' && value.length > 0 && value.length <= max ? value : null;
const percent = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) ? Math.min(100, Math.max(0, Math.round(value * 10) / 10)) : null;
const TOOL_NAME: Record<StoredLoginTool, string> = { pi: 'Pi', opencode: 'OpenCode' };
// Store keys per tool: Pi names its ChatGPT login openai-codex; OpenCode names it openai.
const KEYS: Record<StoredLoginTool, Partial<Record<StoredLoginKind, string[]>>> = {
  pi: { chatgpt: ['openai-codex'], claude: ['anthropic'] },
  opencode: { chatgpt: ['openai'], claude: ['anthropic'], 'opencode-go': ['opencode-go', 'opencode'] },
};

export function storedLoginFile(tool: StoredLoginTool, dataDir?: string, env: NodeJS.ProcessEnv = process.env): string {
  if (dataDir) return join(dataDir, 'auth.json');
  if (tool === 'pi') return join(env.PI_CODING_AGENT_DIR || join(homedir(), '.pi', 'agent'), 'auth.json');
  return join(env.XDG_DATA_HOME || join(homedir(), '.local', 'share'), 'opencode', 'auth.json');
}

/** Which supported logins a tool's store currently holds (names only, never values). */
export async function listStoredLogins(tool: StoredLoginTool, dataDir?: string): Promise<StoredLoginKind[]> {
  const store = object(safeJson(await readSmallFile(storedLoginFile(tool, dataDir), 256 * 1024)));
  return (Object.entries(KEYS[tool]) as Array<[StoredLoginKind, string[]]>).filter(([, keys]) => keys.some((key) => object(store?.[key]))).map(([kind]) => kind);
}

function safeJson(value: string | null): unknown {
  try { return value ? JSON.parse(value) : null; } catch { return null; }
}

function windowFrom(limitId: string, label: string, minutes: number, used: number | null, resetsAt: string | null): UsageWindow {
  return {
    limitId, label, kind: 'provider-reported-quota', usedPercent: used, usedKind: 'provider-reported-quota',
    remainingPercent: used === null ? null : Math.round((100 - used) * 10) / 10, remainingKind: 'calculated-estimate', durationMinutes: minutes, resetsAt,
  };
}

export function normalizeChatgptUsage(input: unknown, now: number): { windows: UsageWindow[]; plan: string | null; email: string | null } {
  const root = object(input);
  const rate = object(root?.rate_limit);
  const windows: UsageWindow[] = [];
  for (const [key, id] of [['primary_window', 'primary'], ['secondary_window', 'secondary']] as const) {
    const window = object(rate?.[key]);
    if (!window) continue;
    const seconds = typeof window.limit_window_seconds === 'number' && window.limit_window_seconds > 0 ? window.limit_window_seconds : null;
    const resetAt = typeof window.reset_at === 'number' ? window.reset_at * 1000
      : typeof window.reset_after_seconds === 'number' ? now + window.reset_after_seconds * 1000 : NaN;
    windows.push(windowFrom(id, `${id} quota`, seconds ? Math.round(seconds / 60) : 0, percent(window.used_percent),
      Number.isFinite(resetAt) && resetAt > 0 ? new Date(resetAt).toISOString() : null));
  }
  const plan = text(root?.plan_type, 40);
  const email = root?.email;
  return { windows: windows.map((window) => ({ ...window, durationMinutes: window.durationMinutes || null })), plan, email: isEmail(email) ? email : null };
}

export function normalizeOpencodeGoUsage(input: unknown): UsageWindow[] {
  const usage = object(object(input)?.usage);
  const windows: UsageWindow[] = [];
  for (const [key, label, minutes] of [['rolling', 'five-hour quota', 300], ['weekly', 'weekly quota', 10080], ['monthly', 'monthly quota', 43200]] as const) {
    const entry = object(usage?.[key]);
    const resetsAt = typeof entry?.resetsAt === 'string' && Number.isFinite(Date.parse(entry.resetsAt)) ? new Date(entry.resetsAt).toISOString() : null;
    const used = percent(entry?.percent);
    if (entry && (used !== null || resetsAt)) windows.push(windowFrom(key, label, minutes, used, resetsAt));
  }
  return windows;
}

export async function readStoredLoginProfile(profile: StoredLoginProfile, options: { fetch?: typeof globalThis.fetch; now?: () => number } = {}): Promise<UsageAccount> {
  const tool = TOOL_NAME[profile.provider];
  const base = { id: profile.id, label: profile.label, provider: profile.provider, plan: null, observedAt: null, windows: [], resetCredits: null } as const;
  const source = `${tool} ${profile.login === 'chatgpt' ? 'ChatGPT' : profile.login === 'claude' ? 'Claude' : 'OpenCode Go'} sign-in`;
  const fail = (code: string, message: string, state: UsageAccount['state'] = 'unavailable'): UsageAccount => ({ ...base, source, state, errors: [{ code, message }] });
  const store = object(safeJson(await readSmallFile(storedLoginFile(profile.provider, profile.dataDir), 256 * 1024)));
  const entry = (KEYS[profile.provider][profile.login] ?? []).map((key) => object(store?.[key])).find(Boolean) ?? null;
  if (!entry) return fail('stored_login_missing', `${tool} has no ${profile.login === 'opencode-go' ? 'OpenCode Go key' : `${profile.login === 'chatgpt' ? 'ChatGPT' : 'Claude'} login`} stored. Sign in from ${tool}.`, 'unauthorized');
  const token = text(entry.access) ?? text(entry.key);
  if (!token) return fail('stored_login_unreadable', `${tool}'s stored login could not be read.`);
  const now = options.now?.() ?? Date.now();
  if (typeof entry.expires === 'number' && entry.expires > 0 && entry.expires <= now) {
    return fail('stored_login_expired', `${tool}'s stored login has expired. Open ${tool} to refresh it.`, 'unauthorized');
  }
  try {
    if (profile.login === 'claude') {
      const result = await fetchClaudeUsage({ id: profile.id, label: profile.label, claudeConfigDir: '' }, token, { fetch: options.fetch, app: tool });
      if (result.kind !== 'ok') return result.kind === 'error' ? { ...fail(result.code, result.message, result.state), retryAfterMs: result.retryAfterMs } as UsageAccount : fail('stored_login_unreadable', 'No Claude login.');
      return { ...result.account, provider: profile.provider, source };
    }
    if (profile.login === 'chatgpt') {
      const accountId = text(entry.accountId, 128) ?? text(object(jwtClaims(token)?.['https://api.openai.com/auth'])?.chatgpt_account_id, 128);
      const response = await fetchJson('https://chatgpt.com/backend-api/wham/usage', { headers: {
        Authorization: `Bearer ${token}`, Accept: 'application/json', 'User-Agent': 'subset-usage/0.0.0', ...(accountId ? { 'ChatGPT-Account-Id': accountId } : {}),
      } }, { fetch: options.fetch });
      if (response.status === 401 || response.status === 403) return fail('chatgpt_unauthorized', `ChatGPT rejected ${tool}'s login. Open ${tool} to sign in again.`, 'unauthorized');
      if (response.status === 429) return { ...fail('chatgpt_rate_limited', 'ChatGPT is rate-limiting usage checks. Subset will try again in a few minutes.'), retryAfterMs: response.retryAfterMs } as UsageAccount;
      if (response.status !== 200 || !object(response.json)) return fail('chatgpt_request_failed', 'Could not read ChatGPT usage for this login.');
      const usage = normalizeChatgptUsage(response.json, now);
      const claims = jwtClaims(token);
      const email = usage.email ?? (isEmail(object(claims?.['https://api.openai.com/profile'])?.email) ? object(claims?.['https://api.openai.com/profile'])!.email as string : null);
      return { ...base, source, plan: usage.plan, email, observedAt: new Date().toISOString(), state: usage.windows.length ? 'ok' : 'partial', windows: usage.windows,
        errors: usage.windows.length ? [] : [{ code: 'missing_limits', message: 'ChatGPT returned no usage windows for this login.' }] };
    }
    const response = await fetchJson('https://opencode.ai/zen/go/v1/usage', { headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' } }, { fetch: options.fetch });
    if (response.status === 401 || response.status === 403) return fail('opencode_unauthorized', 'OpenCode rejected the Go key.', 'unauthorized');
    if (response.status !== 200 || !object(response.json)) return fail('opencode_request_failed', 'Could not read OpenCode Go usage.');
    const windows = normalizeOpencodeGoUsage(response.json);
    return { ...base, source, plan: 'Go', observedAt: new Date().toISOString(), state: windows.length ? 'ok' : 'partial', windows,
      errors: windows.length ? [] : [{ code: 'missing_limits', message: 'OpenCode returned no Go usage windows.' }] };
  } catch {
    return fail('stored_login_request_failed', `Could not read usage for ${tool}'s login.`);
  }
}

