/**
 * Hour-by-day activity for the last `days` days from local history: the sum of usage increases
 * across the given accounts' windows in each hour. Index 0 is the oldest day; hours are local.
 */
export function activityGrid(history: UsageHistory | undefined, accounts: UsageAccount[], now: number, days = 7): { grid: number[][]; max: number; dayStarts: number[] } {
  const today = new Date(now);
  today.setHours(0, 0, 0, 0);
  const dayStarts = Array.from({ length: days }, (_, index) => today.getTime() - (days - 1 - index) * 86_400_000);
  const grid = dayStarts.map(() => new Array<number>(24).fill(0));
  for (const account of accounts) {
    for (const points of Object.values(history?.series[account.id] ?? {})) {
      for (let index = 1; index < points.length; index++) {
        const increase = points[index][1] - points[index - 1][1];
        if (increase <= 0) continue;
        const time = points[index][0];
        const day = dayStarts.findIndex((start) => time >= start && time < start + 86_400_000);
        if (day >= 0) grid[day][new Date(time).getHours()] += increase;
      }
    }
  }
  return { grid, max: Math.max(0, ...grid.flat()), dayStarts };
}
"""
